// Using DeferredRegister (recommended)
private static final DeferredRegister<Block> BLOCKS = DeferredRegister.create(BuiltInRegistries.BLOCK, MODID);

// Direct registry event
NeoForge.EVENT_BUS.addListener((RegisterEvent event) -> {
    if (event.getRegistryKey() == Registries.BLOCK) {
        event.register(new ResourceLocation(MODID, "my_block"), () -> new MyBlock());
    }
});
